package dev.netlab.core;
import dev.netlab.sputnik.core.*;
import java.util.*;
import java.net.*;
import java.io.*;

public final class SputnikTest {
    private static int checks;
    private static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
    private static void rejects(Runnable r,String s){boolean rejected=false;try{r.run();}catch(IllegalArgumentException e){rejected=true;}check(rejected,s);}
    public static Device device(String kind){var d=new Device(kind);SputnikHardware.initialize(d);return d;}
    public static Network network(){var n=new Network();var pc=new Device("pc");Hardware.initializeHost(pc,true);SputnikHardware.audio(pc);pc.ports.get(0).ip="192.168.77.100";pc.gateway="192.168.77.1";var modem=device(SputnikHardware.MODEM);modem.ports.get(0).ip="192.168.77.1";modem.ports.get(4).ip="10.254.77.2";modem.gateway="10.254.77.1";var hub=device(SputnikHardware.HUB);hub.ports.get(0).ip="172.30.77.1";hub.ports.get(4).ip="10.254.77.1";hub.routes.add(new Device.Route("192.168.77.0","255.255.255.0","10.254.77.2"));var gateway=device(SputnikHardware.GATEWAY);gateway.ports.get(0).ip="172.30.77.2";gateway.gateway="172.30.77.1";n.devices.put(1L,pc);n.devices.put(2L,modem);n.devices.put(3L,hub);n.devices.put(4L,gateway);n.wires.add(new Network.Wire(new Network.Endpoint(1,0),new Network.Endpoint(2,0),3,"copper"));n.wires.add(new Network.Wire(new Network.Endpoint(2,4),new Network.Endpoint(3,4),0,"satellite"));n.wires.add(new Network.Wire(new Network.Endpoint(3,0),new Network.Endpoint(4,0),3,"copper"));
        n.linkTransits.put("satellite",(net,wire,from,ready,bytes,protocol)->{boolean up=from.device()==2;var slot=net.clock.send(new Network.Endpoint(3,up?1000:1001),ready,bytes,up?SatelliteModel.UP_MBPS:SatelliteModel.DOWN_MBPS,0,SatelliteModel.ONE_WAY_MS,1);var to=from.equals(wire.a())?wire.b():wire.a();net.traffic.add(new Network.Traffic(from,to,"SAT/"+protocol,1,false,slot.start(),slot.finish(),bytes));return slot.finish();});return n;}
    public static int run(){checks=0;SputnikHardware.init();var geo=SatelliteModel.find("geo-1");check(SatelliteModel.angle(359,1)==2,"azimuth wraps at north");check(SatelliteModel.carriers(14000,12200,14200,12000)&&!SatelliteModel.carriers(14000,12200,14000,12200),"forward and return carriers use distinct Ku frequencies and transponder translation");var aimed=SatelliteModel.signal(geo,180,45,0,1,false,false);check(aimed.quality()==1&&aimed.state().equals("LOCK"),"correctly pointed terminal acquires lock");check(SatelliteModel.signal(geo,0,45,0,1,false,false).quality()==0,"backwards dish cannot lock");check(SatelliteModel.signal(geo,180,45,0,1,true,false).quality()==0,"blocked sky loses lock");check(SatelliteModel.signal(geo,180,45,64,1,false,true).quality()<aimed.quality(),"storm and long coax reduce margin");check(SatelliteModel.signal(geo,180,45,64,4,false,true).quality()>SatelliteModel.signal(geo,180,45,64,1,false,true).quality(),"larger hub dish has more link margin");check(SatelliteModel.signal(geo,Double.NaN,45,0,1,false,false).quality()==0,"invalid pointing cannot create a channel");rejects(()->SatelliteModel.find("fake"),"unknown satellite rejected");
        var hub=device(SputnikHardware.HUB);rejects(()->Hardware.install(hub,"tx0",SputnikHardware.TX),"no hub hot-plugging");Hardware.ensure(hub).powered=false;for(var e:Map.of("control0",SputnikHardware.CONTROL,"tx0",SputnikHardware.TX,"rx0",SputnikHardware.RX).entrySet())Hardware.install(hub,e.getKey(),e.getValue());Hardware.ensure(hub).powered=true;check(SputnikHardware.hubReady(hub)&&hub.ports.size()==5,"three installed hub cards enable existing bearer without phantom ports");Hardware.ensure(hub).powered=false;Hardware.remove(hub,"rx0");Hardware.ensure(hub).powered=true;check(!SputnikHardware.hubReady(hub),"missing receiver disables hub");
        var modem=device(SputnikHardware.MODEM);var dish=device(SputnikHardware.VSAT);check(CableKind.compatible("coax_tx",modem,2,dish,0)&&!CableKind.compatible("coax_tx",modem,2,dish,1),"TX/RX connectors cannot be interchanged");check(!CableKind.compatible("copper",modem,2,dish,0),"Ethernet cannot replace coax");for(String kind:SputnikHardware.KINDS){var d=device(kind);for(var jack:PortLayout.jacks(d,false,0))check(PortLayout.pickRay(d,false,0,jack.x(),jack.y(),-2,jack.x(),jack.y(),.2)==jack.port(),"visible Sputnik port can be selected: "+kind+"/"+jack.port());}
        for(boolean laptop:new boolean[]{false,true}){var pc=new Device("pc");Hardware.initializeHost(pc,laptop);SputnikHardware.audio(pc);SputnikHardware.audio(pc);check(pc.ports.stream().filter(p->p.name.equals("AudioOut")).count()==1,"host audio upgrade is idempotent");var jacks=PortLayout.jacks(pc,false,0);for(int a=0;a<jacks.size();a++)for(int b=a+1;b<jacks.size();b++)check(!jacks.get(a).contains(jacks.get(b).x(),jacks.get(b).y()),"host audio jack does not overlap Ethernet or Console");}
        var n=network();byte[] payload=new byte[16384];new Random(43).nextBytes(payload);var result=n.transmit(1,"172.30.77.2","tcp",1080,payload);check(result.result().success()&&result.result().path().equals(List.of(1L,2L,3L,4L))&&Arrays.equals(result.payload(),payload),"opaque browser bytes follow PC, VSAT, HUB, Internet gateway");check(n.cursor>=375_000_000L,"uplink has real GEO propagation delay");long previous=n.cursor;result=n.transmit(4,"192.168.77.100","tcp",1080,payload);check(result.result().success()&&Arrays.equals(result.payload(),payload)&&n.cursor-previous>=375_000_000L,"return path needs hub route and carries unchanged bytes with GEO delay");n.devices.get(3L).routes.clear();check(!n.transmit(4,"192.168.77.100","tcp",1080,payload).result().success(),"missing return route blocks real browser bytes");n=network();n.wires.remove(1);check(!n.transmit(1,"172.30.77.2","tcp",1080,payload).result().success(),"losing satellite bearer stops browser traffic");
        try{for(String host:List.of("127.0.0.1","10.0.0.1","172.16.0.1","192.168.1.1","169.254.169.254","100.64.0.1","::1","fc00::1","fe80::1","224.0.0.1","192.0.2.1","198.51.100.1","203.0.113.1"))check(!InternetTarget.publicAddress(InetAddress.getByName(host)),"proxy rejects local/reserved destination: "+host);for(String host:List.of("1.1.1.1","8.8.8.8","203.0.112.1","198.51.99.1","2606:4700:4700::1111"))check(InternetTarget.publicAddress(InetAddress.getByName(host)),"public web destination accepted: "+host);
            var bytes=new ByteArrayOutputStream();bytes.write(new byte[]{5,1,0,5,1,0,3,11});bytes.write("example.com".getBytes(java.nio.charset.StandardCharsets.US_ASCII));bytes.write(new byte[]{1,(byte)187});var out=new ByteArrayOutputStream();var target=SocksProxy.handshake(new ByteArrayInputStream(bytes.toByteArray()),out);check(target[0].equals("example.com")&&target[1].equals("443")&&Arrays.equals(out.toByteArray(),new byte[]{5,0}),"SOCKS domain CONNECT preserves remote DNS name and HTTPS port");
        }catch(IOException e){throw new AssertionError(e);}rejects(()->InternetTarget.validate("example.com",22),"proxy does not expose arbitrary server ports");rejects(()->InternetTarget.validate("bad/host",443),"invalid authority rejected");return checks;}
}
